  // Ikona jako znacznik SVG. `cls` trafia na <svg>; ikona jest dekoracją (aria-hidden), nazwę niesie przycisk.
  function _icon(name, cls) {
    var def = UI_ICONS[name];
    if (!def) return '';
    var d = typeof def === 'string' ? def : def.d;
    var fill = typeof def === 'object' && def.fill;
    var dots = name === 'more';
    return '<svg' + (cls ? ' class="' + cls + '"' : '') + ' viewBox="0 0 24 24" aria-hidden="true" focusable="false" ' +
      (fill ? 'fill="currentColor" stroke="none"' :
        'fill="none" stroke="currentColor" stroke-width="' + (dots ? '3.4' : '1.8') + '" stroke-linecap="round" stroke-linejoin="round"') +
      '><path d="' + d + '"></path></svg>';
  }

  // ───────────────────────────────────────────
  // UI - OKNA
  // ───────────────────────────────────────────
  // Menedżer okien wyglądu 0.38 (design/SURFACES.md §1–§5, IMPLEMENTATION.md §5): rodzaje i warstwy,
  // przeciąganie z magnesem, dokowanie panelu, zmiana rozmiaru, zapis układu, dialogi z pułapką fokusu,
  // pigułka panelu, uchwyty krawędziowe, dymki, menu i powiadomienia. Mechanika przeniesiona z planszy
  // DeskG (design/canvas/project/DeskG.dc.html), sprawdzonej scenariuszami w headless Chrome.

  // Odstęp od krawędzi przeglądarki i od innego okna (§2.3); ten sam w położeniu domyślnym, z menu położenia
  // i z magnesu, więc menu zaznacza róg, do którego okno przyciągnął magnes.
  var WIN_GAP = 12;
  var WIN_MAGNET = 16;     // zasięg magnesu
  var WIN_DRAG_FROM = 4;   // próg przeciągania (§2.2)
  var WIN_DOCK_BAND = 24;  // pas dokowania panelu przy prawej krawędzi (§2.3)
  var WIN_PILL = [176, 36];
  // Okno z warstwy panelu podniesione nad okno robocze ma własną warstwę `raised`, więc kliknięcie w okno robocze go
  // nie przykrywa. Każda warstwa mieści 48 okien (restack); pigułka (399) stoi nad nimi, a pod dialogami.
  var WIN_LAYER = { edge: 100, panel: 200, tool: 200, float: 200, hud: 200, work: 300, raised: 350, dialog: 400, notice: 400 };
  var WIN_MIN = { panel: [280, 360], tool: [320, 200] };
  var WIN_MOVABLE = { panel: 1, tool: 1, float: 1, hud: 1 };
  var WIN_SIZABLE = { panel: 1, tool: 1 };
  var WIN_MODAL = { dialog: 1, notice: 1 };
  var WIN_EASE_IN = 'cubic-bezier(0.2, 0, 0, 1)';
  var WIN_EASE_OUT = 'cubic-bezier(0.3, 0, 1, 1)';
  var WIN_FOCUSABLE = 'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), ' +
    'textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

  function _clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

  // Chrome zostawia ostatni stan animacji sterowanej przewijaniem (cień nagłówka, cieniowanie krawędzi), gdy
  // treść przestaje się przewijać: oś czasu staje się nieaktywna i nie wraca do zera (np. przewinięta karta
  // Ustawień, potem krótka karta). Kontener bez czego przewijać dostaje is-static, a CSS zdejmuje te animacje;
  // nowa animacja przy osi znów aktywnej startuje od właściwego miejsca. Sprawdzenie najwyżej raz na klatkę.
  function _uiWatchScroll(el) {
    var raf = 0;
    var check = function () {
      raf = 0;
      var st = el.scrollHeight <= el.clientHeight + 1;
      if (el.classList.contains('is-static') !== st) el.classList.toggle('is-static', st);
    };
    var later = function () { if (!raf) raf = requestAnimationFrame(check); };
    new ResizeObserver(later).observe(el);
    new MutationObserver(later).observe(el, { childList: true, subtree: true, attributes: true, attributeFilter: ['hidden', 'class', 'style'] });
    check();
  }
  function _uiFull() { return _uiEnsure().app.getAttribute('data-b24t-motion') !== 'lite'; }

  // Ochrona przed przypadkowym kliknięciem: element, który właśnie się pojawił albo zmienił treść w miejscu
  // (powiadomienie, okno, dymek samouczka), przez UI_ARM_MS nie przyjmuje wskaźnika na swoich kontrolkach.
