          if (mySeq !== _customFillSeq) return;
          _customSetMetricsPending(false);
          if (!info) return;
          _customFillMetrics(info);
          var _dFld = _$('b24t-news-f-date');
          var _dBefore = _dFld ? _dFld.value : '';
          _customSetAuto(_dFld, info.date, 'date', 'Data wykryta automatycznie');
          _customSetAuto(_$('b24t-news-f-hour'),   info.hour);
          _customSetAuto(_$('b24t-news-f-minute'), info.minute);
          // Podpis dobieramy tylko wtedy, gdy DOM nic nie dał (odtwarzacz rolek, post bez
          // przerysowanego modala) — w treści z DOM-u użytkownik może już coś poprawiać.
          if (!_social.content && info.caption) {
            _customSetAuto(_$('b24t-news-f-content'),
                           info.caption.replace(/\s+/g, ' ').trim().slice(0, 600),
                           'fill', 'Automatycznie wypełniono z treści strony');
            _customSetAuto(_$('b24t-news-f-title'),
                           _socialTitleFromText(info.caption).slice(0, 400), 'fill');
          }
          if (info.lang) _customLangWarn(info.lang);
          // Dup-check pyta o miesiąc wzięty z pola daty. Jeśli data dopiero teraz się pojawiła
          // albo zmieniła, poprzednie zapytanie poszło w zły zakres — trzeba je powtórzyć.
          if (_dFld && _dFld.value && _dFld.value !== _dBefore && state.projectId) {
            _customDupCheck((_$('b24t-news-f-url') || {}).value || '', state.projectId);
          }
